var wave1 = new SineWave(250, 300, 10);
var wave2 = new SineWave(350, 150, 5);
var wave3 = new SineWave(50, 350, 2);

function setup() {
  createCanvas(500, 500);
}

function draw() {
  fill(255);
  noStroke();
  rect(0, 0, width, height);
  noFill();
  stroke(0);
  for (y = 0; y < height; y += 5) {
    beginShape();
    for (x = 0; x <= width; x += 5) {
      let a = (wave1.amplitude(x, y) + wave2.amplitude(x, y) + wave3.amplitude(x, y)) * 2;
      vertex(x, y + a);
    }
    endShape();
  }
}

class SineWave {
cx;
cy;
wavelength;

  constructor(cx, cy, wavelength) {
    this.cx = cx;
    this.cy = cy;
    this.wavelength = wavelength;
  }

  amplitude(x, y) {
    let dx = x - this.cx;
    let dy = y - this.cy;
    return sin((sqrt(dx * dx + dy * dy) - frameCount) / this.wavelength);
  }
}
